// pushSettings holds the resolved push configuration from a single settings load.
type pushSettings struct {
	// remote is the git remote name to use for pushing (the user's push remote).
	remote string
	// checkpointURL is the derived URL for pushing checkpoint branches.
	// When set, checkpoint/trails branches are pushed directly to this URL
	// instead of the remote name. Empty means use the remote name.
	checkpointURL string
	// pushDisabled is true if push_sessions is explicitly set to false.
	pushDisabled bool
}

// pushTarget returns the target to use for git push/fetch commands for checkpoint branches.
// If a checkpoint URL is configured, returns that; otherwise returns the remote name.
func (ps *pushSettings) pushTarget() string {
	if ps.checkpointURL != "" {
		return ps.checkpointURL
	}
	return ps.remote
}

// hasCheckpointURL returns true if a dedicated checkpoint URL is configured.
func (ps *pushSettings) hasCheckpointURL() bool {
	return ps.checkpointURL != ""
}

// resolvePushSettings loads settings once and returns the resolved push config.
// If a structured checkpoint_remote is configured (e.g., {"provider": "github", "repo": "org/repo"}):
//   - Derives the checkpoint URL from the push remote's protocol (SSH vs HTTPS)
//   - Ignores the setting when it looks inherited from an upstream project rather
//     than configured by this developer, so a fork contributor's checkpoints are
//     not pushed into the upstream's checkpoint repo (see
//     remote.checkpointRemoteIsInherited for how ownership is established)
//   - If a checkpoint branch doesn't exist locally, attempts to fetch it from the URL
//
// The push itself handles failures gracefully (doPushRef warns and continues),
// so no reachability check is needed here.
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:       pushRemoteName,
		pushDisabled: s.IsPushSessionsDisabled(),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}
	checkpointURL, enabled, err := remote.PushURL(ctx, pushRemoteName)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}
	if !enabled || checkpointURL == "" {
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the v1 checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	if err := fetchMetadataBranchIfMissing(ctx, checkpointURL); err != nil {
		logging.Warn(ctx, "checkpoint-remote: failed to fetch metadata branch",
			slog.String("error", err.Error()),
		)
	}

	return ps
}

//go:build integration

package integration

import (
	"bytes"
	"encoding/json"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// =============================================================================
// Single-remote checkpoint sync (ENT-1451)
//
// Checkpoint data syncs to exactly one elected git remote:
// strategy_options.checkpoint_push_remote (fail-closed when the named remote
// is not configured) -> origin -> sole remote -> first
// remote in .git/config order. The branch's tracking config deliberately does
// not participate; see TestCheckpointSyncRemote_BranchTrackingDoesNotReroute.
// The pre-push gate drops checkpoint sync for
// every other remote and for raw-URL pushes, on both backends. The dedicated
// checkpoint_remote URL mode is exempt. These are end-to-end acceptance tests
// through the simulated hook flow; the election precedence itself is
// unit-tested in strategy/checkpoint_sync_remote_test.go.
// =============================================================================

// remoteTarget names a configured remote and the bare repo backing it.
type remoteTarget struct {
	name    string
	bareDir string
}

// queuedCheckpointRefCount returns the git-refs push-discovery queue length
// for the test repo. The queue lives in the git common dir, which for the
// plain (non-worktree) TestEnv repos is .git.
func queuedCheckpointRefCount(t *testing.T, env *TestEnv) int {
	t.Helper()
	refs, err := checkpoint.NewPushQueue(filepath.Join(env.RepoDir, ".git")).Peek()
	if err != nil {
		t.Fatalf("read push queue: %v", err)
	}
	return len(refs)
}

// assertSingleRemoteRouting drives the pre-push flow first against the
// non-elected remote (no checkpoint data may land there; on git-refs the push
// queue must survive), then against the elected remote (the checkpoint lands
// and the queue drains). Shared by the default-election and config-override
// scenarios, which are mirror images of each other.
func assertSingleRemoteRouting(t *testing.T, env *TestEnv, checkpointID string, gated, elected remoteTarget) {
	t.Helper()

	if checkpointID == "" {
		t.Fatal("should have a checkpoint ID after condensation")
	}
	if !env.CheckpointsPresentLocally() {
		t.Fatal("checkpoints should exist locally after condensation")
	}
	if env.usingGitRefs() && queuedCheckpointRefCount(t, env) == 0 {
		t.Fatal("git-refs push queue should have entries after condensation")
	}

	// Pre-push to the non-elected remote: gated, no checkpoint data escapes.
	env.RunPrePush(gated.name)
	if env.CheckpointsPresentOnRemote(gated.bareDir) {
		t.Errorf("checkpoints should NOT be on non-elected remote %q", gated.name)
	}
	if env.usingGitRefs() && queuedCheckpointRefCount(t, env) == 0 {
		t.Error("push queue should be preserved after a gated pre-push")
	}

	// Pre-push to the elected remote: checkpoint data lands, queue drains.
	env.RunPrePush(elected.name)
	if !env.CheckpointExistsOnRemote(elected.bareDir, checkpointID) {
		t.Errorf("checkpoint %s should be on elected remote %q", checkpointID, elected.name)
	}
	if env.usingGitRefs() && queuedCheckpointRefCount(t, env) != 0 {
		t.Error("push queue should drain after pushing to the elected remote")
	}
	if env.CheckpointsPresentOnRemote(gated.bareDir) {
		t.Errorf("non-elected remote %q must never receive checkpoint data", gated.name)
	}
}

// TestCheckpointSyncRemote_DefaultElection_OnlyOriginReceivesCheckpoints
// verifies that with two configured remotes and no override, checkpoint data
// syncs only to origin (the default election): a pre-push for "publish"
// carries nothing, a pre-push for "origin" delivers the checkpoint.
func TestCheckpointSyncRemote_DefaultElection_OnlyOriginReceivesCheckpoints(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		bareOrigin := env.SetupBareRemote()
		barePublish := env.SetupNamedBareRemote("publish")
		checkpointID := createCheckpointedCommit(t, env, "Add gate module", "gate.go", "package gate", "Add gate module")

		assertSingleRemoteRouting(t, env, checkpointID,
			remoteTarget{name: "publish", bareDir: barePublish},
			remoteTarget{name: "origin", bareDir: bareOrigin})
	})
}

// TestCheckpointSyncRemote_ConfigOverride_RoutesToNamedRemote verifies the
// mirror image: with checkpoint_push_remote set to "publish", origin is the
// gated remote and publish receives the checkpoint data.
func TestCheckpointSyncRemote_ConfigOverride_RoutesToNamedRemote(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		bareOrigin := env.SetupBareRemote()
		barePublish := env.SetupNamedBareRemote("publish")

		env.PatchSettings(map[string]any{
			"strategy_options": map[string]any{
				"checkpoint_push_remote": "publish",
			},
		})

		checkpointID := createCheckpointedCommit(t, env, "Add router module", "router.go", "package router", "Add router module")

		assertSingleRemoteRouting(t, env, checkpointID,
			remoteTarget{name: "origin", bareDir: bareOrigin},
			remoteTarget{name: "publish", bareDir: barePublish})

		// Status reflects the override election.
		st := statusSyncJSONOutput(t, env)
		if st.CheckpointSyncRemote != "publish" || st.CheckpointSyncRemoteSource != "config" {
			t.Errorf("status should report remote %q from source %q, got %q from %q",
				"publish", "config", st.CheckpointSyncRemote, st.CheckpointSyncRemoteSource)
		}
	})
}

// TestCheckpointSyncRemote_BranchTrackingDoesNotReroute pins the regression
// that removed the tracking tier before merge: a branch tracking a non-origin
// remote must NOT move checkpoint sync there.
//
// Election is compared against the remote of the push being made, so electing
// the tracking remote made every push to a different remote a silent no-op —
// caught by TestAlternates_RelativeObjectAlternate_CheckpointSync, which
// clones with `-o base` and pushes checkpoints to a separately added origin.
// It also elected a remote the read paths cannot see: resume and explain
// resolve checkpoints through origin's remote-tracking refs.
//
// The fork topology this tier was meant to serve — origin is the unpushable
// base repo, you push to your own fork — is served explicitly by
// checkpoint_push_remote (TestCheckpointSyncRemote_ConfigOverride_RoutesToNamedRemote).
func TestCheckpointSyncRemote_BranchTrackingDoesNotReroute(t *testing.T) {
	t.Parallel()

package strategy

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// refsPushDestination is the single place checkpoint refs are pushed to.
type refsPushDestination struct {
	// target is passed to git push and to the recovery fetch: a remote name, or a URL.
	target string
	// checkpointRemote records that target came from a configured
	// checkpoint_remote. It cannot be recovered from target's shape — a
	// resolved push URL is URL-shaped too — and it decides both how the
	// destination is named and whether the "a checkpoint remote is configured"
	// hint applies.
	checkpointRemote bool
	// ignoredPushURLs counts the push URLs of a multi-URL remote that will NOT
	// receive checkpoint refs. Zero in every single-destination topology.
	ignoredPushURLs int
}

// resolveRefsPushDestination picks the single destination for checkpoint-ref
// pushes.
//
// Checkpoint refs need ONE deterministic destination, because the push-discovery
// queue records only a ref (`{"ref": …}`) with no per-destination state: a ref is
// removed from the queue once "the push" succeeds, so "the push" has to mean one
// place. Relying on git's fan-out across a remote's several push URLs breaks that
// in both directions — a single failing URL fails the whole invocation and no ref
// unqueues even though some URLs took it, and an unreachable FIRST URL makes git
// die() before it reaches any later URL at all.
//
// So when a remote carries more than one push URL we target its first push URL
// directly (the one git itself would push to first) and ignore the rest. The
// recovery fetch in fetchAndRebaseRefCommon uses the same target, so — unlike the
// fan-out path, which reconciled the remote's FETCH url while pushing to its
// pushurls — the URL we reconcile is finally the URL we push to.
//
// Consequences, deliberately accepted:
//   - Checkpoint refs live in exactly one repository. Cloning that repository
//     resolves them (its url becomes the clone's fetch URL); cloning a different
//     mirror of the same code does not. Mirroring checkpoints to several
//     repositories is what checkpoint_remote is for.
//   - A first push URL that REJECTS a ref (non-fast-forward) no longer lets later
//     URLs receive it. git would have carried on to them; we stop. That is the
//     price of a deterministic destination, and it is the case the queue can
//     actually reason about.
//
// The git-branch backend deliberately keeps git's fan-out: its v1 branch is a
// single shared ref with no queue to keep coherent, and mirroring it to every
// push URL is behavior users configure their remotes for.
//
// A single push URL keeps the remote NAME as the target rather than resolving it
// to a URL, so the overwhelmingly common topology behaves exactly as before —
// remote-tracking refs still update, output still says "origin", and no
// URL-keyed promisor config appears.
//
// Call this only once there is something to push: it spawns `git remote get-url`
// and its result is unused on an empty queue.
func resolveRefsPushDestination(ctx context.Context, ps pushSettings) refsPushDestination {
	target := ps.pushTarget()

	// A configured checkpoint_remote, or a push straight to a URL (git hands the
	// hook a bare URL verbatim), is already a single explicit destination.
	if ps.hasCheckpointURL() || remote.IsURL(target) {
		return refsPushDestination{target: target, checkpointRemote: ps.hasCheckpointURL()}
	}

	urls, err := remote.GetPushURLs(ctx, target)
	if err != nil {
		// Not a configured remote, or git could not report its URLs. Keep the
		// target as given; the push itself will report any real problem.
		logging.Debug(ctx, "git-refs push: could not enumerate push URLs; using target as given",
			slog.String("target", target),
			slog.String("error", err.Error()),
		)
	}
	if len(urls) < 2 {
		return refsPushDestination{target: target}
	}
	return refsPushDestination{target: urls[0], ignoredPushURLs: len(urls) - 1}
}

// display names the destination for progress and warning output.
//
// Deliberately not displayPushTarget: that maps ANY URL to the literal words
// "checkpoint remote", which was only ever true because a URL target implied a
// configured checkpoint_remote. A push URL we resolved ourselves is URL-shaped
// but is not a checkpoint remote, so it is named by its (redacted) URL.
func (d refsPushDestination) display() string {
	switch {
	case d.checkpointRemote:
		return "checkpoint remote"
	case d.ignoredPushURLs > 0:
		return fmt.Sprintf("%s (first of %d push URLs)", remote.RedactURLOrPath(d.target), d.ignoredPushURLs+1)
	default:
		return remote.RedactURLOrPath(d.target)
	}
}

// warnIgnoredPushURLs tells the user that checkpoint refs are going to one URL of
// a multi-URL remote — otherwise the choice is invisible and looks like the other
// mirrors silently lost their checkpoints. Call it only when there are refs to
// push, so a no-op push stays quiet.
func (d refsPushDestination) warnIgnoredPushURLs(ctx context.Context) {
	if d.ignoredPushURLs == 0 {
		return
	}
	fmt.Fprintf(stderrWriter, "[entire] Checkpoints go to one repository: %s. %d other push URL(s) of this remote will not receive them.\n",
		d.display(), d.ignoredPushURLs)
	fmt.Fprintln(stderrWriter, "[entire] To store checkpoints in a specific repository instead, set checkpoint_remote in .entire/settings.json.")
	logging.Info(ctx, "git-refs push: multi-URL remote, pushing checkpoint refs to the first push URL only",
		slog.String("target", remote.RedactURLOrPath(d.target)),
		slog.Int("ignored_push_urls", d.ignoredPushURLs),
	)
}

